import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import { I } from '../icons.jsx';
import { Tag } from './Tag.jsx';
import { Dropdown } from './Dropdown.jsx';
import { Input } from './Input.jsx';
import { contactSchema } from '../../lib/page-schemas/contact.js';
import { listPaths } from '../../lib/page-engine/resolve.js';

/* ───────────────────────────────────────────────────────────────
   VariableSchemaPicker — tree-style schema dropdown for the
   New Variable form. Same mechanics as AccountConditions' rule
   picker (PathButton + tree with search + array drill-in) but
   wired INLINE rather than absolute-positioned: when the tree
   opens, it takes vertical space in the form so the surrounding
   modal body expands / scrolls naturally instead of clipping a
   floating popover.

   • Width = 100% of the parent column (matches the input row).
   • Tree expansion + arrow-key nav + array drill-in carry over.
   • No portal, no fixed positioning — just normal block flow.
─────────────────────────────────────────────────────────────── */

const TYPE_TONE = {
  string:   'neutral',
  number:   'brand',
  currency: 'success',
  date:     'warning',
  bool:     'info',
  array:    'neutral',
  object:   'neutral',
  variable: 'brand',
};
const TYPE_DOT = {
  string:   'var(--gb-text-tertiary)',
  number:   'var(--gb-brand-label)',
  currency: 'var(--gb-success-fg)',
  date:     'var(--gb-warning-fg)',
  bool:     'var(--gb-info-fg)',
  array:    'var(--gb-text-muted)',
  object:   'transparent',
  variable: 'var(--gb-brand-label)',
};

/* Build the flat node list for a schema. Default is the unified
   contact/account schema; callers can pass a different schema (e.g. the
   order schema for order templates) via the `schema` prop. */
function buildSchemaNodes(schema) {
  try {
    return listPaths(schema, /* sample */ {}).map((n) => ({
      path:     n.path,
      label:    n.label || n.path,
      type:     n.type,
      isFolder: n.type === 'object' || n.type === 'array',
      depth:    n.path.split(/[.[]/).filter(Boolean).length - 1,
    }));
  } catch { return []; }
}
const SCHEMA_NODES = buildSchemaNodes(contactSchema);
const canonicalPath = (p) => (p || '').replace(/\[(?:-?\d+|any|none)\]/g, '[0]');

export function VariableSchemaPicker({ value, onChange, placeholder = '— pick a field —', varNames = [], allowQuantifiers = false, overlay = false, embedArrayRow = true, schema = null }) {
  const [open, setOpen] = useState(false);
  /* Node set + type lookup for the active schema (default contact/account). */
  const NODES = useMemo(() => (schema ? buildSchemaNodes(schema) : SCHEMA_NODES), [schema]);
  const typeForPath = useMemo(() => {
    const byPath = Object.fromEntries(NODES.map((n) => [n.path, n.type]));
    return (p) => byPath[canonicalPath(p)] || 'string';
  }, [NODES]);
  const type = typeForPath(value);
  /* Surface array selector only when the active path actually
     contains an array segment. Variables resolve to a single
     value — no any / none modes — so the dropdown carries the
     three single-value picks: first (=[0]), last (=[-1]), or a
     specific index. */
  const detected = useMemo(() => parseArraySegment(value), [value]);
  /* mode='index' with index=0 writes [0] — identical to mode='first'
     in the path. So local override forces "Index" to stick when the
     user picks it explicitly even if the number happens to be 0. The
     override resets whenever the path's array name changes (user
     picked a different array in the tree). */
  const [forceIndex, setForceIndex] = useState(false);
  const arrayKey = detected?.arrayName || null;
  const prevKey = useRef(arrayKey);
  useEffect(() => {
    if (prevKey.current !== arrayKey) {
      setForceIndex(false);
      prevKey.current = arrayKey;
    }
  }, [arrayKey]);
  const arrayInfo = detected && {
    ...detected,
    mode: forceIndex ? 'index' : detected.mode,
  };
  return (
    <div style={{ position: 'relative', width: '100%', minWidth: 0 }}>
      <PathButton
        path={value}
        type={type}
        open={open}
        placeholder={placeholder}
        onClick={() => setOpen((o) => !o)}
      />
      <AnimatePresence initial={false}>
        {open && (
          <InlineSchemaTree
            currentPath={canonicalPath(value)}
            varNames={varNames}
            overlay={overlay}
            nodes={NODES}
            onClose={() => setOpen(false)}
            onSelect={(node) => {
              onChange(typeof node === 'string' ? node : node.path);
              setOpen(false);
            }}
          />
        )}
      </AnimatePresence>
      {embedArrayRow && arrayInfo && (
        <ArraySelectorRow
          arrayName={arrayInfo.arrayName}
          mode={arrayInfo.mode}
          index={arrayInfo.index}
          allowQuantifiers={allowQuantifiers}
          onChange={(mode, index) => {
            setForceIndex(mode === 'index');
            onChange(rewriteArrayIndex(value, mode, index));
          }}
        />
      )}
    </div>
  );
}

/* Detects the FIRST `[N]` segment in a path and reports its
   mode + index. Returns null when the path has no array. */
function parseArraySegment(path) {
  if (!path) return null;
  const m = /\[(-?\d+|any|none)\]/.exec(path);
  if (!m) return null;
  /* The bit before `[` is the array's field name — kept short for
     the row's caption ("orders" rather than the full prefix). */
  const arrayName = path.slice(0, m.index).split('.').pop() || 'items';
  const tok = m[1];
  if (tok === 'any' || tok === 'none') return { arrayName, mode: tok, index: 0 };
  const n = parseInt(tok, 10);
  return {
    arrayName,
    mode: n === 0 ? 'first' : n === -1 ? 'last' : 'index',
    index: n >= 0 ? n : 0,
  };
}

/* Rewrite the first `[N]` in `path` according to mode + index.
   first → [0], last → [-1], index → [N] (clamped to >= 0). */
function rewriteArrayIndex(path, mode, index) {
  if (!path) return path;
  const next = mode === 'first' ? '[0]'
    : mode === 'last' ? '[-1]'
    : mode === 'any'  ? '[any]'
    : mode === 'none' ? '[none]'
    : `[${Math.max(0, index | 0)}]`;
  return path.replace(/\[(?:-?\d+|any|none)\]/, next);
}

const ARRAY_MODE_BASE = [
  { id: 'first', label: 'First' },
  { id: 'last',  label: 'Last' },
  { id: 'index', label: 'Index' },
];
/* Quantifiers — only for match conditions (allowQuantifiers). 'any' =
   the condition matches if ANY array item passes; 'none' = if no item
   does. Variables resolve to a single value, so they never see these. */
const ARRAY_MODE_QUANT = [
  { id: 'any',  label: 'Any match' },
  { id: 'none', label: 'No match' },
];

function ArraySelectorRow({ arrayName, mode, index, onChange, allowQuantifiers = false }) {
  const modeOptions = allowQuantifiers ? [...ARRAY_MODE_BASE, ...ARRAY_MODE_QUANT] : ARRAY_MODE_BASE;
  return (
    <div style={{
      display: 'flex', alignItems: 'center', gap: 8,
      marginTop: 6,
      padding: '8px 10px',
      background: 'var(--gb-surface-2)',
      border: '1px solid var(--gb-border-default)',
      borderRadius: 'var(--gb-r-sm)',
    }}>
      <span style={{
        fontFamily: 'var(--gb-font-mono)',
        fontSize: 11,
        color: 'var(--gb-text-muted)',
        whiteSpace: 'nowrap',
      }}>
        {arrayName}[]
      </span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <Dropdown
          size="sm"
          value={mode}
          options={modeOptions}
          onChange={(id) => onChange(id, index)}
        />
      </div>
      {mode === 'index' && (
        <div style={{ width: 72 }}>
          <Input
            size="sm"
            type="number"
            min={0}
            value={String(index)}
            onChange={(e) => {
              const v = parseInt(e.target.value, 10);
              onChange('index', Number.isFinite(v) ? Math.max(0, v) : 0);
            }}
          />
        </div>
      )}
    </div>
  );
}

function PathButton({ path, type, open, onClick, placeholder }) {
  const fadeMask = 'linear-gradient(to right, black calc(100% - 18px), transparent 100%)';
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 6,
        width: '100%',
        minWidth: 0,
        boxSizing: 'border-box',
        height: 28,
        padding: '0 8px',
        background: open ? 'var(--gb-brand-tint-medium)' : 'var(--gb-surface-2)',
        border: '1px solid ' + (open ? 'var(--gb-brand-tint-border)' : 'var(--gb-border-default)'),
        borderRadius: 'var(--gb-r-sm)',
        color: open ? 'var(--gb-brand-label)' : 'var(--gb-text-primary)',
        cursor: 'pointer',
        fontFamily: 'var(--gb-font-mono)',
        fontSize: 11.5,
        fontWeight: 600,
        textAlign: 'left',
        transition: 'background-color .15s, border-color .15s, color .15s',
      }}
    >
      <span style={{
        width: 8, height: 8, borderRadius: 2,
        background: path ? (TYPE_DOT[type] || 'var(--gb-text-muted)') : 'var(--gb-text-ghost)',
        flexShrink: 0,
      }} />
      <span style={{
        flex: 1,
        minWidth: 0,
        overflow: 'hidden',
        whiteSpace: 'nowrap',
        WebkitMaskImage: fadeMask,
        maskImage: fadeMask,
        color: path ? 'inherit' : 'var(--gb-text-muted)',
      }}>{path || placeholder}</span>
      <motion.span
        animate={{ rotate: open ? 180 : 0 }}
        transition={{ duration: 0.18 }}
        style={{
          fontSize: 10,
          color: open ? 'var(--gb-brand-label)' : 'var(--gb-text-muted)',
          fontFamily: 'var(--gb-font-mono)',
          display: 'inline-flex',
          flexShrink: 0,
        }}
      >▾</motion.span>
    </button>
  );
}

/* ── Inline tree — opens in flow, not absolute. The parent
   modal/form body's overflow handles scroll. ────────────────── */
function InlineSchemaTree({ currentPath, varNames = [], overlay = false, onClose, onSelect, nodes = SCHEMA_NODES }) {
  const [search, setSearch] = useState('');
  const [expanded, setExpanded] = useState(() => initialExpansion(currentPath));
  const [focusedIdx, setFocusedIdx] = useState(0);
  const searchRef = useRef(null);

  useEffect(() => {
    const r = requestAnimationFrame(() => { try { searchRef.current?.focus(); } catch {} });
    return () => cancelAnimationFrame(r);
  }, []);

  const schemaRows = useMemo(() => filterAndProject(nodes, search, expanded), [nodes, search, expanded]);
  const varRows = useMemo(() => {
    if (!varNames.length) return [];
    const q = search.trim().toLowerCase();
    return varNames
      .filter((n) => !q || n.toLowerCase().includes(q))
      .map((n) => ({ path: `vars.${n}`, label: n, type: 'variable', isFolder: false, depth: 0, isVar: true }));
  }, [varNames, search]);
  /* Variables first, then the schema tree — one combined list so the
     ↓↑ ↵ keyboard nav + focusedIdx work across both sections. */
  const rows = useMemo(() => [...varRows, ...schemaRows], [varRows, schemaRows]);
  useEffect(() => { setFocusedIdx(0); }, [search]);

  const toggleExpand = (path) => {
    setExpanded((s) => {
      const next = new Set(s);
      if (next.has(path)) next.delete(path); else next.add(path);
      return next;
    });
  };

  const pickRow = (r) => {
    if (r.type === 'array') onSelect(r);
    else if (r.isFolder) toggleExpand(r.path);
    else onSelect(r);
  };

  const onKey = (e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setFocusedIdx((i) => Math.min(i + 1, rows.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setFocusedIdx((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      const r = rows[focusedIdx];
      if (r) pickRow(r);
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      const r = rows[focusedIdx];
      if (r?.isFolder) toggleExpand(r.path);
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      const r = rows[focusedIdx];
      if (r?.isFolder && expanded.has(r.path)) toggleExpand(r.path);
    } else if (e.key === 'Escape') {
      onClose();
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: 'auto' }}
      exit={{ opacity: 0, height: 0 }}
      transition={{ duration: 0.22, ease: [0.4, 0, 0.2, 1] }}
      style={{
        overflow: 'hidden',
        ...(overlay ? {
          /* Float over the content below instead of pushing it down.
             Absolute (relative to the picker's positioned parent) so it
             stays in the page's scaled coordinate space — a fixed /
             document.body portal would mis-place under data-gb-scale. */
          position: 'absolute', top: 'calc(100% + 4px)', left: 0, zIndex: 50,
          width: '100%', minWidth: 280, maxWidth: 360,
          boxShadow: '0 10px 28px rgba(0,0,0,.34)', borderRadius: 'var(--gb-r-md)',
        } : { marginTop: 4 }),
      }}
    >
      <div style={{
        background: 'var(--gb-surface-1)',
        border: '1px solid var(--gb-border-default)',
        borderRadius: 'var(--gb-r-md)',
        overflow: 'hidden',
      }}>
        <div style={{
          padding: '8px 10px',
          borderBottom: '1px solid var(--gb-border-subtle)',
          display: 'flex', alignItems: 'center', gap: 6,
          background: 'var(--gb-surface-2)',
        }}>
          <I.search size={11} style={{ color: 'var(--gb-text-muted)' }} />
          <input
            ref={searchRef}
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            onKeyDown={onKey}
            placeholder="Filter fields + variables · ↓↑ ↵"
            style={{
              flex: 1,
              height: 24,
              background: 'transparent',
              border: 'none',
              outline: 'none',
              fontSize: 12,
              fontFamily: 'var(--gb-font-mono)',
              color: 'var(--gb-text-primary)',
            }}
          />
          <span style={{
            fontSize: 9.5, color: 'var(--gb-text-muted)',
            fontFamily: 'var(--gb-font-mono)',
          }}>{rows.length}</span>
        </div>
        <div style={{ maxHeight: 280, overflow: 'auto', padding: '4px 6px 8px' }}>
          {rows.length === 0 ? (
            <div style={{
              padding: 14, textAlign: 'center',
              fontSize: 11, color: 'var(--gb-text-muted)',
            }}>No fields match</div>
          ) : rows.map((r, i) => (
            <React.Fragment key={r.path}>
              {i === 0 && varRows.length > 0 && <TreeSection label="Variables" />}
              {i === varRows.length && varRows.length > 0 && schemaRows.length > 0 && <TreeSection label="Schema" />}
              <PathRow
                node={r}
                focused={i === focusedIdx}
                expanded={expanded.has(r.path)}
                isCurrent={r.path === currentPath}
                onMouseEnter={() => setFocusedIdx(i)}
                onClick={() => pickRow(r)}
                onToggleExpand={() => toggleExpand(r.path)}
              />
            </React.Fragment>
          ))}
        </div>
      </div>
    </motion.div>
  );
}

function TreeSection({ label }) {
  if (!label) return null;
  return (
    <div style={{
      padding: '7px 6px 3px', fontSize: 9, fontWeight: 800, letterSpacing: 0.8,
      textTransform: 'uppercase', color: 'var(--gb-text-muted)',
    }}>{label}</div>
  );
}

function initialExpansion(currentPath) {
  const out = new Set();
  if (currentPath) {
    const parts = currentPath.split('.');
    let acc = '';
    for (let i = 0; i < parts.length - 1; i++) {
      acc = acc ? `${acc}.${parts[i]}` : parts[i];
      out.add(acc);
    }
    return out;
  }
  out.add('contact');
  out.add('stats');
  return out;
}

function filterAndProject(nodes, search, expanded) {
  const q = search.trim().toLowerCase();
  return nodes.filter((n) => {
    if (q) return n.path.toLowerCase().includes(q) || n.label.toLowerCase().includes(q);
    if (n.depth === 0) return true;
    const parts = n.path.split(/[.[]/).filter(Boolean);
    let acc = '';
    for (let i = 0; i < parts.length - 1; i++) {
      acc = acc ? `${acc}.${parts[i]}` : parts[i];
      acc = acc.replace(/\.0\]$/, '[0]');
      if (expanded.has(acc)) continue;
      const baseKey = acc.replace(/\[\d+\]$/, '');
      if (baseKey !== acc && expanded.has(baseKey)) continue;
      return false;
    }
    return true;
  });
}

function PathRow({ node, focused, expanded, isCurrent, onClick, onMouseEnter, onToggleExpand }) {
  const indent = node.depth * 12;
  const leafLabel = node.path.split('.').slice(-1)[0].replace(/\[0\]/g, '');
  const showTag = !node.isFolder || node.type === 'array';
  return (
    <div
      role="button"
      tabIndex={-1}
      onClick={onClick}
      onMouseEnter={onMouseEnter}
      style={{
        display: 'grid',
        gridTemplateColumns: `${indent + 16}px 1fr auto 16px`,
        gap: 6,
        alignItems: 'center',
        width: '100%',
        padding: '4px 6px',
        background: focused
          ? 'var(--gb-brand-tint-medium)'
          : isCurrent
            ? 'var(--gb-brand-tint-soft)'
            : 'transparent',
        border: '1px solid ' + (focused
          ? 'var(--gb-brand-tint-border)'
          : isCurrent
            ? 'var(--gb-brand-tint-border)'
            : 'transparent'),
        borderRadius: 'var(--gb-r-sm)',
        color: 'var(--gb-text-secondary)',
        cursor: 'pointer',
        textAlign: 'left',
        fontFamily: 'var(--gb-font-sans)',
        transition: 'background-color .12s, border-color .12s',
        userSelect: 'none',
      }}
    >
      <div style={{
        paddingLeft: indent,
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'flex-end',
      }}>
        {node.isFolder ? (
          <button
            type="button"
            onClick={(e) => { e.stopPropagation(); onToggleExpand?.(); }}
            aria-label={expanded ? 'Collapse' : 'Expand'}
            style={{
              width: 14, height: 14,
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
              background: 'transparent', border: 'none', cursor: 'pointer',
              padding: 0,
              color: 'var(--gb-text-muted)',
              fontFamily: 'var(--gb-font-mono)',
              fontSize: 9,
            }}
          >
            <motion.span
              animate={{ rotate: expanded ? 90 : 0 }}
              transition={{ duration: 0.15 }}
              style={{ display: 'inline-flex' }}
            >▸</motion.span>
          </button>
        ) : (
          <span style={{
            width: 6, height: 6, borderRadius: 2,
            background: TYPE_DOT[node.type] || 'var(--gb-text-muted)',
            opacity: focused ? 1 : 0.7,
          }} />
        )}
      </div>
      <span style={{
        fontFamily: 'var(--gb-font-mono)',
        fontSize: 11.5,
        fontWeight: node.isFolder ? 700 : 500,
        color: focused
          ? 'var(--gb-brand-label)'
          : node.isFolder ? 'var(--gb-text-primary)' : 'var(--gb-text-secondary)',
        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
      }}>
        {node.isFolder ? node.path : leafLabel}
      </span>
      {showTag && (
        <Tag size="xs" tone={TYPE_TONE[node.type] || 'neutral'}>{node.type}</Tag>
      )}
      <div style={{ display: 'inline-flex', justifyContent: 'flex-end' }}>
        {isCurrent && <I.check size={10} strokeWidth={3} style={{ color: 'var(--gb-brand-label)' }} />}
      </div>
    </div>
  );
}
